def transform(grid):
    """Overlay four aligned binary color masks using priority 9 > 4 > 8 > 5."""
    panels = [
        [[grid[r][start + c] for c in range(4)] for r in range(4)]
        for start in (0, 5, 10, 15)
    ]
    priority = {5: 1, 8: 2, 4: 3, 9: 4}
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            colors = [panel[r][c] for panel in panels if panel[r][c] != 0]
            row.append(max(colors, key=priority.__getitem__) if colors else 0)
        out.append(row)
    return out
